#define BOXOS_MOSAIC_H

#define BOXOS_MOSAIC_QUADRANTS_ROWS 2
#define BOXOS_MOSAIC_SEXTANTS_ROWS 3
#define BOXOS_MOSAIC_OCTANTS_ROWS 4

